<script setup lang="ts">const route=useRoute(),{lang}=useLocale(); const {data:number,error}=await useFetch<any>(`/api/numbers/${route.params.id}`); if(error.value) throw createError({statusCode:error.value.statusCode||410,statusMessage:lang.value==='ru'?'Номер больше не доступен':'Number is no longer available'}); usePageSeo(computed(()=>lang.value==='ru'?'Входящие SMS публичного номера':'Incoming SMS for a public number'),computed(()=>lang.value==='ru'?'Обновляемая демонстрационная лента сообщений публичного номера.':'A refreshed simulated message feed for a public number.'),{noindex:true});</script>
<template><div class="shell page narrow"><span class="kicker">Public feed / noindex</span><h1>{{number.phone}}</h1><p class="lead">{{lang==='ru'?'Публичная демонстрационная лента. Никому не сообщайте личные данные и не используйте номер для важных аккаунтов.':'A public simulated feed. Never share personal information or use this number for important accounts.'}}</p><div class="message-list"><article v-for="m in number.messages" :key="m.id"><img :src="`/images/services/${m.serviceCode}.webp`"><div><b>{{m.serviceName}}</b><p>{{m.text}}</p><small>{{new Date(m.receivedAt).toLocaleString(lang)}}</small></div></article></div><PremiumBanner medium="sms_timeout"/></div></template>
